import{_ as t,o,c as r,a2 as a}from"./chunks/framework.vLhlLNVn.js";const n="/assets/adapter-startet-nicht.DIwnam97.svg",f=JSON.parse('{"title":"Connection and adapter start","description":"","frontmatter":{"order":1,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/04.fehlerbehebung/01.verbindung-und-start.md"},"headers":[],"relativePath":"adapter/wled/fehlerbehebung/verbindung-und-start.md","filePath":"adapter/wled/fehlerbehebung/verbindung-und-start.md","lastUpdated":null}'),s={name:"adapter/wled/fehlerbehebung/verbindung-und-start.md"};function i(d,e,l,h,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="connection-and-adapter-start" tabindex="-1">Connection and adapter start <a class="header-anchor" href="#connection-and-adapter-start" aria-label="Permalink to &quot;Connection and adapter start&quot;">​</a></h1><p><a id="adapter-not-start-stop-responding"></a></p><h2 id="why-doesn-t-the-adapter-start-after-an-update-or-why-does-it-stop-responding" tabindex="-1">Why doesn&#39;t the adapter start after an update, or why does it stop responding? <a class="header-anchor" href="#why-doesn-t-the-adapter-start-after-an-update-or-why-does-it-stop-responding" aria-label="Permalink to &quot;Why doesn&#39;t the adapter start after an update, or why does it stop responding?&quot;">​</a></h2><p><strong>In short:</strong> Look at the log of the instance <code>wled.&lt;instance&gt;</code> first. The known causes are: requirements such as the Node.js version not met, an incompletely installed update, bugs in older adapter versions, and in v0.9.2 a polling interval of 0 or devices that were added after the start. The table below matches the log lines to their causes.</p><h3 id="how-to-proceed" tabindex="-1">How to proceed <a class="header-anchor" href="#how-to-proceed" aria-label="Permalink to &quot;How to proceed&quot;">​</a></h3><ol><li>In Admin, open the &quot;Log&quot; tab and look for the lines of the instance <code>wled.&lt;instance&gt;</code> and the <code>host.&lt;host&gt;</code> lines right after the instance starts. If the adapter doesn&#39;t start at all, the error is often in the host lines with <code>Caught by controller</code>.</li><li>Compare the lines with the table below and follow the solution.</li><li>Restart the instance afterwards.</li><li>If the error remains, set the log level of the instance to &quot;debug&quot;, restart it and attach the log excerpt to a <a href="https://github.com/DrozmotiX/ioBroker.wled/issues" target="_blank" rel="noreferrer">GitHub issue</a>. Replace IP and MAC addresses first.</li></ol><h3 id="known-causes-and-log-lines" tabindex="-1">Known causes and log lines <a class="header-anchor" href="#known-causes-and-log-lines" aria-label="Permalink to &quot;Known causes and log lines&quot;">​</a></h3><p><img src="'+n+'" alt="Decision tree: check in order whether the installation reports a Node.js version that is too old, whether &quot;Cannot find module&quot; is in the log, whether messages from old versions appear, whether many &quot;Unable to initialise&quot; lines come, whether the load is high without an error message, or whether a device no longer responds after an outage. If nothing fits, attach a debug log to a GitHub issue."></p><table tabindex="0"><thead><tr><th>Log line (excerpt)</th><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td>No start after the update; the installation reports a Node.js version that is too old</td><td>In v0.9.2 the adapter needs Node.js 20 or newer, js-controller 6.0.11 or newer and Admin 7.6.17 or newer.</td><td>Update Node.js, js-controller or Admin.</td></tr><tr><td><code>Caught by controller[0]: Error: Cannot find module &#39;axios&#39;</code></td><td>The update wasn&#39;t installed completely; a library of the adapter is missing.</td><td>Install the adapter again in the &quot;Adapters&quot; tab, or install a newer version.</td></tr><tr><td><code>[handleStates] TypeError: Cannot read property &#39;initialized&#39; of undefined</code></td><td>Bug in versions before v0.6.7, fixed in v0.6.7.</td><td>Update the adapter.</td></tr><tr><td><code>Caught by controller[0]: State attribute definition missing for …</code>, after which the instance stops</td><td>Bug in v0.5.x. Since v0.7.1 the message is only a debug message without consequences.</td><td>Update the adapter.</td></tr><tr><td>Many lines <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> and <code>Device 192.168.x.y unavailable (attempt n/5), will retry in … seconds</code></td><td>A device is switched off or can&#39;t be reached. The adapter keeps running, but the log fills up with every attempt.</td><td>Switch the device on, or delete it if you no longer use it.</td></tr><tr><td>After every error, a second line <code>Sentry disabled, error caught : …</code></td><td>The adapter reports every error twice. It is the same error.</td><td>Only look at the first line.</td></tr><tr><td>No error message, but the adapter stops responding and the load is high</td><td>&quot;Intervall in seconds&quot; is set to 0. The requests then run without a pause.</td><td>Set the interval to at least 1 second; the default is 30 seconds.</td></tr><tr><td>No error message, but a device no longer responds after an outage</td><td>The device was added after the adapter started, via &quot;Discover new devices&quot;, by IP, or because the Bonjour search only found it later. In v0.9.2 no monitoring starts for such devices, so they don&#39;t reconnect after an outage.</td><td>Restart the instance.</td></tr></tbody></table><p>The two lines about <code>State attribute definition missing</code> and <code>Cannot read property &#39;initialized&#39;</code> come from old versions. If you still see them today, you are running an old adapter version.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The setting &quot;Max retry attempts&quot; applies to all devices of the instance together. There is no setting per device.</p></div><h3 id="from-v0-9-3" tabindex="-1">From v0.9.3 <a class="header-anchor" href="#from-v0-9-3" aria-label="Permalink to &quot;From v0.9.3&quot;">​</a></h3><p><strong>From v0.9.3:</strong> The adapter needs Node.js 22 or newer and Admin 7.6.20 or newer. Check this before updating.</p><p><strong>From v0.9.3:</strong> If the polling interval is below 1 second or the number of retries is invalid, the adapter replaces it with the default at startup and warns once: <code>Invalid polling interval &quot;0&quot;, using 30 seconds</code> or <code>Invalid number of retry attempts &quot;0&quot;, using 5</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/924" target="_blank" rel="noreferrer">#924</a>). Correct the setting so that the warning goes away.</p><p><strong>From v0.9.3:</strong> An outage appears in the log as a single warning, for example <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> or <code>Heartbeat of device 192.168.x.y failed, will try to reconnect</code>. The further attempts only appear at the level &quot;debug&quot; (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/903" target="_blank" rel="noreferrer">#903</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>).</p><p><strong>From v0.9.3:</strong> Every error appears in the log only once. The hand-over to Sentry only appears at the level &quot;debug&quot; (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/913" target="_blank" rel="noreferrer">#913</a>).</p><p><strong>From v0.9.3:</strong> Devices that are added after the start are monitored as well and reconnect after an outage without a restart (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). <code>_info._online</code> becomes <code>false</code> if a device doesn&#39;t answer for two polling intervals (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/900" target="_blank" rel="noreferrer">#900</a>).</p><p><strong>From v0.9.3:</strong> The adapter discards a command to a device that is offline, with the warning <code>Device &lt;MAC&gt; (192.168.x.y) is offline, command for &lt;State&gt; discarded</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>). <code>on</code> and <code>bri</code> keep their last value when the device goes offline and when the adapter starts (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p><p><strong>From v0.10.0:</strong> The setting is called &quot;Polling interval&quot;. You find it in the instance settings on the &quot;Settings&quot; tab under &quot;Connection&quot;, next to &quot;Max retry attempts&quot;. The form only accepts an interval of 1 second or more, and 1 to 20 for the retries (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><strong>From v0.10.0:</strong> If you write a command to a device that counts as offline, the adapter tries to reach it right away instead of waiting for the next check. If the device answers, the command goes out. Only if it doesn&#39;t answer does the adapter discard the command with the warning above (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/939" target="_blank" rel="noreferrer">#939</a>). There are at least 5 seconds between two such attempts for the same device.</p><p><strong>See also:</strong> <a href="./befehle-wirken-nicht#script-not-ps-wled-ignores">Why doesn&#39;t my script set ps or on?</a> · <a href="./../erste-schritte/installation#wled-firmware-requirements-adapter-need">Which requirements does the adapter need?</a> · <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">How often does the adapter try to reach an offline device again?</a> · <a href="./../referenz/log-meldungen#warning-state-attribute-definition-missing">What does &quot;State attribute definition missing&quot; mean?</a></p><p><a id="adapter-stop-working-after-wled"></a></p><h2 id="why-does-the-adapter-stop-working-after-a-wled-firmware-update-or-segments-only-work-on-one-device" tabindex="-1">Why does the adapter stop working after a WLED firmware update, or segments only work on one device? <a class="header-anchor" href="#why-does-the-adapter-stop-working-after-a-wled-firmware-update-or-segments-only-work-on-one-device" aria-label="Permalink to &quot;Why does the adapter stop working after a WLED firmware update, or segments only work on one device?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="wled-shown-offline-after-restart"></a></p><h2 id="why-is-wled-shown-as-offline-after-a-restart-or-update-and-takes-a-long-time-to-reconnect" tabindex="-1">Why is WLED shown as offline after a restart or update and takes a long time to reconnect? <a class="header-anchor" href="#why-is-wled-shown-as-offline-after-a-restart-or-update-and-takes-a-long-time-to-reconnect" aria-label="Permalink to &quot;Why is WLED shown as offline after a restart or update and takes a long time to reconnect?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="wled-devices-show-red-offline"></a></p><h2 id="why-do-all-wled-devices-show-red-or-offline-or-the-esp-crashes" tabindex="-1">Why do all WLED devices show red or offline, or the ESP crashes? <a class="header-anchor" href="#why-do-all-wled-devices-show-red-or-offline-or-the-esp-crashes" aria-label="Permalink to &quot;Why do all WLED devices show red or offline, or the ESP crashes?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="about-multiple-adapter-processes-already"></a></p><h2 id="what-do-i-do-about-multiple-adapter-processes-already-running-or-onunload-errors" tabindex="-1">What do I do about multiple adapter processes, &quot;already running&quot; or onUnload errors? <a class="header-anchor" href="#what-do-i-do-about-multiple-adapter-processes-already-running-or-onunload-errors" aria-label="Permalink to &quot;What do I do about multiple adapter processes, &quot;already running&quot; or onUnload errors?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',33)])])}const g=t(s,[["render",i]]);export{f as __pageData,g as default};
